const p = msg.payload;
if (!p || typeof p !== 'object' || !p.vid) return null;

// Starting thresholds: tune them later
const MIN_SAMPLES = 2;            // consecutive readings needed
const rules = [
  { type: 'HARSH_BRAKING',      cond: p.ax <= -0.35,        value: p.ax },
  { type: 'HARSH_ACCELERATION', cond: p.ax >= 0.30,         value: p.ax },
  { type: 'SHARP_CORNERING',    cond: Math.abs(p.ay) >= 0.35, value: p.ay },
  { type: 'OVERSPEED',          cond: p.speed > 50,         value: p.speed },
  { type: 'ENGINE_OVERHEAT',    cond: p.temp !== undefined && p.temp >= 105, value: p.temp }
];

let state = context.get('state') || {};
state[p.vid] = state[p.vid] || {};
const s = state[p.vid];
const out = [];

for (const r of rules) {
  const k = s[r.type] = s[r.type] || { n: 0, active: false };
  if (p.ign === 1 && r.cond) {
    k.n++;
    if (k.n >= MIN_SAMPLES && !k.active) {
      k.active = true;
      out.push({ payload: {
        ts: p.ts, vid: p.vid, type: r.type, value: r.value,
        speed: p.speed, lat: p.lat, lon: p.lon
      }});
    }
  } else {
    k.n = 0;
    k.active = false;
  }
}

context.set('state', state);
return out.length ? [out] : null;

const p = msg.payload;
if (!p || typeof p !== 'object' || !p.vid) return null;

let trips = context.get('trips') || {};
let t = trips[p.vid];

// 1) Event message (comes from "detect events")
if (p.type) {
  if (t) t.events[p.type] = (t.events[p.type] || 0) + 1;
  context.set('trips', trips);
  return null;
}

// 2) Telemetry message
if (p.ign === 1 && !t) {
  t = trips[p.vid] = {
    id: p.vid + '-' + p.ts, vid: p.vid,
    startTs: p.ts, lastTs: p.ts,
    distKm: 0, idleSec: 0, overSec: 0,
    speedSum: 0, n: 0, maxSpeed: 0, events: {}
  };
}
if (!t) { context.set('trips', trips); return null; }

let dt = 1;                           // ESP32 publishes once per second of its own clock
t.lastTs = p.ts;

if (p.ign === 1) {
  t.distKm += (p.speed / 3600) * dt;
  if (p.speed < 1)  t.idleSec += dt;
  if (p.speed > 50) t.overSec += dt;
  t.speedSum += p.speed;
  t.n++;
  t.maxSpeed = Math.max(t.maxSpeed, p.speed);
  context.set('trips', trips);
  return null;
}

// Ignition OFF => trip ended: compute score
const e = t.events;
const b = e.HARSH_BRAKING || 0;
const a = e.HARSH_ACCELERATION || 0;
const c = e.SHARP_CORNERING || 0;
const o = e.ENGINE_OVERHEAT || 0;
const overMin = t.overSec / 60;
const idleMin = t.idleSec / 60;

// Starting weights: tune them and justify them in the report
const raw = 8*b + 6*a + 5*c + 10*o + 3*overMin + 2*idleMin;
const score = Math.max(0, Math.round(100 - (raw / Math.max(t.distKm, 1)) * 2));
const label = score >= 85 ? 'GOOD' : (score >= 70 ? 'AVERAGE' : 'RISKY');

const summary = {
  trip_id: t.id, vid: t.vid,
  start: t.startTs, end: p.ts,
  duration_s: p.ts - t.startTs,
  distance_km: Number(t.distKm.toFixed(2)),
  avg_speed: t.n ? Number((t.speedSum / t.n).toFixed(1)) : 0,
  max_speed: t.maxSpeed,
  idle_min: Number(idleMin.toFixed(1)),
  overspeed_min: Number(overMin.toFixed(1)),
  events: e,
  score: score, rating: label
};

delete trips[p.vid];
context.set('trips', trips);

// keep history for the dashboard later
const hist = global.get('tripHistory') || [];
hist.push(summary);
global.set('tripHistory', hist.slice(-200));

return { payload: summary };

const p = msg.payload;
if (!p || typeof p !== 'object' || p.lat === undefined) return null;
return { payload: {
  name: p.vid,
  lat: p.lat,
  lon: p.lon,
  icon: "car",
  layer: "Vehicles",
  speed: p.speed
}};

// Replaces the code of the existing 'trip cost' node.
// For every finished trip: computes the extra cost, saves the trip in a log, and
// sends per-vehicle averages (all trips) to 'fleet state'.
const p = msg.payload;
if (!p || !p.trip_id) return null;

// ===== ASSUMPTIONS: replace with sourced values and cite them in the report =====
const FUEL_PRICE = 20.5;          // EGP per liter (diesel, Oct 2026: see report references)
const IDLE_L_PER_MIN = 0.015;     // liters per minute of idling (example)
const COST = { HARSH_BRAKING: 3, HARSH_ACCELERATION: 2, SHARP_CORNERING: 1.5, ENGINE_OVERHEAT: 50 }; // EGP per event (example)
const OVERSPEED_EGP_PER_MIN = 1.0; // extra fuel while speeding (example)
const TRIPS_PER_MONTH = 60;       // trips per vehicle per month (example)
const MAX_LOG = 5000;             // trips kept in the log

const e = p.events || {};
let cost = 0, eventCount = 0;
for (const k in COST) cost += (e[k] || 0) * COST[k];
for (const k in e) eventCount += e[k];
cost += (p.overspeed_min || 0) * OVERSPEED_EGP_PER_MIN;
cost += (p.idle_min || 0) * IDLE_L_PER_MIN * FUEL_PRICE;

const endSec = (p.end > 1.7e9) ? p.end : Math.round(Date.now() / 1000);
const entry = {
  vid: p.vid, end: endSec, duration: p.duration_s, distance: p.distance_km,
  avgSpeed: p.avg_speed, maxSpeed: p.max_speed, score: p.score, rating: p.rating,
  events: Object.keys(e).map(k => k.replace(/_/g, ' ') + ' x' + e[k]).join(', ') || 'none',
  eventCount: eventCount,
  cost: Math.round(cost * 10) / 10
};

let log = global.get('tripLog') || [];
log.push(entry);
if (log.length > MAX_LOG) log = log.slice(-MAX_LOG);
global.set('tripLog', log);

// averages per vehicle over the whole log
const by = {};
log.forEach(t => {
  const v = by[t.vid] = by[t.vid] || { vid: t.vid, cost: 0, trips: 0 };
  v.cost += t.cost; v.trips++;
});
const rows = Object.values(by).map(v => {
  const perTrip = v.cost / v.trips;
  return { vid: v.vid, perTrip: Math.round(perTrip * 10) / 10,
           monthly: Math.round(perTrip * TRIPS_PER_MONTH), trips: v.trips };
});
rows.sort((a, b) => b.perTrip - a.perTrip);
return { payload: rows };

// Keeps the latest state + short history of every vehicle and sends it to the dashboard
const OFFLINE_AFTER_MS = 6000;
const HIST = 120;                    // samples kept per vehicle (about 2 minutes)
let fleet = context.get('fleet') || {};
const p = msg.payload;

function get(vid) {
  return fleet[vid] = fleet[vid] || {
    vid: vid, speed: 0, fuel: 0, temp: 0, ign: 0, lastSeen: 0,
    lastEvent: '-', lastEventTs: 0, events: 0, recent: [],
    scoreSum: 0, trips: 0, lastScore: null, lastTrip: null,
    perTrip: null, monthly: null,
    hSpeed: [], hTemp: [], hFuel: []
  };
}
function push(arr, x) { arr.push(x); if (arr.length > HIST) arr.shift(); }
const pretty = (s) => String(s).replace(/_/g, ' ');

if (Array.isArray(p)) {                      // cost rows from 'trip cost'
  p.forEach(r => { const v = get(r.vid); v.perTrip = r.perTrip; v.monthly = r.monthly; });
} else if (p && typeof p === 'object' && p.vid) {
  const v = get(p.vid);
  if (p.type) {                              // event from 'detect events'
    v.lastEvent = p.type; v.lastEventTs = Date.now(); v.events++;
    v.recent.unshift({ type: p.type, value: p.value, ts: Date.now() });
    if (v.recent.length > 6) v.recent.pop();
  } else if (p.trip_id) {                    // trip summary from 'trip & score'
    v.lastScore = p.score; v.scoreSum += p.score; v.trips++;
    const ev = Object.keys(p.events || {}).map(k => pretty(k) + ' x' + p.events[k]).join(', ');
    v.lastTrip = {
      distance: p.distance_km, duration: p.duration_s, avgSpeed: p.avg_speed,
      maxSpeed: p.max_speed, score: p.score, rating: p.rating, events: ev || 'none'
    };
  } else if (p.speed !== undefined) {        // telemetry
    v.speed = p.speed; v.fuel = p.fuel; v.temp = p.temp; v.ign = p.ign;
    v.lastSeen = Date.now();
    push(v.hSpeed, p.speed); push(v.hTemp, p.temp); push(v.hFuel, p.fuel);
  }
}
context.set('fleet', fleet);

// ---- build the message for the dashboard ----
const now = Date.now();
const clamp = (x) => Math.max(0, Math.min(100, x));
// chart plot area inside an SVG of 320 x 120: x from 40 to 310, y from 10 (top) to 100 (bottom)
const X0 = 40, PW = 270, Y0 = 10, PH = 90;
function yOf(val, lo, hi) {
  return Y0 + PH - ((Math.max(lo, Math.min(hi, val)) - lo) / (hi - lo)) * PH;
}
function pts(arr, lo, hi) {                  // SVG polyline points, newest sample on the right
  return arr.map((y, i) => {
    const x = X0 + ((i + (HIST - arr.length)) / (HIST - 1)) * PW;
    return x.toFixed(1) + ',' + yOf(y, lo, hi).toFixed(1);
  }).join(' ');
}

const rows = Object.values(fleet).map(v => ({
  vid: v.vid,
  online: (now - v.lastSeen) < OFFLINE_AFTER_MS,
  ign: v.ign,
  speed: Math.round(v.speed),
  speedPct: clamp(v.speed / 120 * 100),
  fuel: Math.round(v.fuel),
  fuelPct: clamp(v.fuel),
  temp: Math.round(v.temp),
  lastEvent: v.lastEvent,
  eventAgoS: v.lastEventTs ? Math.round((now - v.lastEventTs) / 1000) : null,
  events: v.events,
  recent: v.recent.map(e => ({
    type: pretty(e.type),
    value: (typeof e.value === 'number') ? Math.round(e.value * 100) / 100 : e.value,
    agoS: Math.round((now - e.ts) / 1000)
  })),
  lastTrip: v.lastTrip,
  lastScore: v.lastScore,
  avgScore: v.trips ? Math.round(v.scoreSum / v.trips) : null,
  trips: v.trips,
  perTrip: v.perTrip,
  monthly: v.monthly,
  speedPts: pts(v.hSpeed, 0, 120),
  tempPts: pts(v.hTemp, 40, 130),
  fuelPts: pts(v.hFuel, 0, 100),
  tempLimitY: yOf(105, 40, 130).toFixed(1)
}));
rows.sort((a, b) => a.vid.localeCompare(b.vid));

const scored = rows.filter(r => r.avgScore !== null);
const summary = {
  total: rows.length,
  online: rows.filter(r => r.online).length,
  fleetAvg: scored.length ? Math.round(scored.reduce((s, r) => s + r.avgScore, 0) / scored.length) : null,
  atRisk: scored.filter(r => r.avgScore < 70).length
};
return { payload: { vehicles: rows, summary: summary } };

// Builds the ranking and the trip log for the 'Drivers and Trips' page
const TRIPS_PER_MONTH = 60;                  // same assumption as in 'trip cost'
const log = global.get('tripLog') || [];

const d = new Date();
const periods = {
  today: new Date(d.getFullYear(), d.getMonth(), d.getDate()).getTime(),
  week:  Date.now() - 7 * 86400000,
  month: new Date(d.getFullYear(), d.getMonth(), 1).getTime(),
  all:   0
};

const ranking = {};
for (const key of Object.keys(periods)) {
  const by = {};
  log.forEach(t => {
    if (t.end * 1000 < periods[key]) return;
    const v = by[t.vid] = by[t.vid] || { vid: t.vid, trips: 0, scoreSum: 0, km: 0, events: 0, cost: 0 };
    v.trips++; v.scoreSum += t.score; v.km += t.distance; v.events += t.eventCount; v.cost += t.cost;
  });
  ranking[key] = Object.values(by).map(v => {
    const perTrip = v.cost / v.trips;
    return {
      vid: v.vid, trips: v.trips,
      avgScore: Math.round(v.scoreSum / v.trips),
      km: Math.round(v.km * 10) / 10,
      events: v.events,
      cost: Math.round(v.cost * 10) / 10,
      perTrip: Math.round(perTrip * 10) / 10,
      monthly: Math.round(perTrip * TRIPS_PER_MONTH)
    };
  }).sort((a, b) => b.avgScore - a.avgScore);
}

return { payload: { periods: periods, ranking: ranking, log: log.slice(-300).reverse(), total: log.length } };
